function Stat({title,value,icon,footer,bars,accent='green'}:{title:string;value:string;icon:ReactNode;footer:ReactNode;bars:number[];accent?:string}){return <section className="stat-card"><div className="stat-label">{title}<span>{icon}</span></div><div className="stat-body"><strong>{value}</strong><div className={`spark-bars ${accent}`} aria-hidden="true">{bars.map((v,i)=><i key={i} style={{height:`${v}%`}}/>)}</div></div><div className="stat-footer">{footer}</div></section>}
function Detail({label,value}:{label:string;value:ReactNode}){return <div className="detail"><span>{label}</span><strong>{value}</strong></div>}
function BlockDialog({hosts,defaultEndpoint,onClose,onSubmit}:{hosts:Endpoint[];defaultEndpoint:string;onClose:()=>void;onSubmit:(input:MitigationInput)=>string|null}){const [input,setInput]=useState<MitigationInput>({endpointId:defaultEndpoint!=='all'?defaultEndpoint:hosts[1].id,protocol:'TCP',port:4444,direction:'Outbound',address:'',reason:'',expires:'30 minutes'}),[error,setError]=useState(''),[ack,setAck]=useState(false);const change=(key:keyof MitigationInput,value:string|number)=>{setInput(i=>({...i,[key]:value}));setError('')};return <Modal title="New mitigation request" description="Propose a narrowly scoped action. This is a simulated approval workflow." onClose={onClose}><form onSubmit={e=>{e.preventDefault();const err=onSubmit(input);if(err)setError(err)}}><div className="form-grid"><label className="form-label full">Endpoint<Select label="Mitigation endpoint" value={input.endpointId} onChange={v=>change('endpointId',v)} options={hosts.filter(h=>h.status!=='revoked').map(h=>({value:h.id,label:h.hostname}))}/></label><label className="form-label">Protocol<Select label="Protocol" value={input.protocol} onChange={v=>change('protocol',v)} options={['TCP','UDP'].map(v=>({value:v,label:v}))}/></label><label className="form-label">Local port<input aria-label="Local port" type="number" min="1" max="65535" required value={input.port||''} onChange={e=>change('port',Number(e.target.value))}/></label><label className="form-label">Direction<Select label="Direction" value={input.direction} onChange={v=>change('direction',v)} options={['Inbound','Outbound'].map(v=>({value:v,label:v}))}/></label><label className="form-label">Expiration<Select label="Expiration" value={input.expires} onChange={v=>change('expires',v)} options={['15 minutes','30 minutes','1 hour','2 hours'].map(v=>({value:v,label:v}))}/></label><label className="form-label full">Remote address<input aria-label="Remote address" placeholder="Single IPv4 address, e.g. 203.0.113.87" required value={input.address} onChange={e=>change('address',e.target.value)}/></label><label className="form-label full">Investigation reason<textarea aria-label="Investigation reason" required minLength={12} placeholder="Describe the supporting evidence and intended scope…" value={input.reason} onChange={e=>change('reason',e.target.value)}/></label></div><div className="warning-box"><AlertTriangle size={18}/><p>Protected ports and broad scopes are blocked. No endpoint command will be sent.</p></div><label className="checkbox-label"><input type="checkbox" required checked={ack} onChange={e=>setAck(e.target.checked)}/>I understand this request is a frontend simulation.</label>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><Button type="button" variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={!ack}>Create demo request</Button></div></form></Modal>}
function UserDialog({onClose,onSubmit}:{onClose:()=>void;onSubmit:(u:{name:string;email:string;role:string})=>void}){const [name,setName]=useState(''),[email,setEmail]=useState(''),[role,setRole]=useState('Analyst');return <Modal title="Add demo user" description="Creates a local preview row. No invitation or email is sent." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSubmit({name:name.trim(),email:email.trim(),role})}}><label className="form-label">Full name<input required minLength={2} value={name} onChange={e=>setName(e.target.value)}/></label><label className="form-label">Email address<input required type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label className="form-label">Role<Select label="New user role" value={role} onChange={setRole} options={['Analyst','Administrator'].map(v=>({value:v,label:v}))}/></label><div className="modal-actions"><Button type="button" variant="outline" onClick={onClose}>Cancel</Button><Button type="submit">Add to demo</Button></div></form></Modal>}
